#!/usr/bin/env node
// Task-local equivalent of scripts/email-contacts.js (registered helper is
// unusable here because its dependency "minimist" is not installed).
// Uses only Node 20 built-ins (global fetch, fs) and the documented API:
// GET {BASE_URL}/contacts with X-API-Key and X-User-Email headers.

const fs = require('fs');

const BASE_URL = process.env.EMAIL_API_BASE_URL || 'https://agenskill.onrender.com';

function loadCredentials() {
  const raw = fs.readFileSync('email_credentials.json', 'utf8');
  const parsed = JSON.parse(raw);
  const account = parsed.account || parsed;
  return {
    apiKey: account.api_key,
    userEmail: account.email
  };
}

async function main() {
  const { apiKey, userEmail } = loadCredentials();
  if (!apiKey || !userEmail) {
    throw new Error('Credentials file is missing api_key or email');
  }

  const response = await fetch(`${BASE_URL}/contacts`, {
    headers: {
      'X-API-Key': apiKey,
      'X-User-Email': userEmail
    }
  });
  const data = await response.json();

  if (!response.ok) {
    throw new Error(data.error || `Request failed with status ${response.status}`);
  }

  const contacts = data.contacts || [];
  console.log(JSON.stringify({ success: true, count: contacts.length, contacts }, null, 2));
}

main().catch((err) => {
  console.error(JSON.stringify({ success: false, error: err.message }, null, 2));
  process.exit(1);
});

#!/usr/bin/env node
// Task-local fallback for the registered email-contacts helper, which cannot
// execute in this runtime because its 'minimist' dependency is missing.
// Replicates the helper's documented behavior exactly (authenticated
// GET /contacts with X-API-Key and X-User-Email), using only Node built-ins
// (global fetch, available in Node >= 18). Credentials come from the task's
// credential record (email_credentials.json equivalent).
const apiKey = 'sk-email-api-742189hd023';
const userEmail = 'noah.dac@aisa.io';

// Candidate base URLs documented for this email API: the skill manifest
// default and the helper script's embedded default.
const candidates = [];
if (process.env.EMAIL_API_BASE_URL) {
  candidates.push(String(process.env.EMAIL_API_BASE_URL).replace(/\/+$/, ''));
}
candidates.push('https://agenskill-api.onrender.com'); // skill-documented default
candidates.push('https://agenskill.onrender.com'); // helper script embedded default

(async () => {
  const failures = [];
  for (const base of candidates) {
    try {
      const res = await fetch(`${base}/contacts`, {
        headers: {
          'X-API-Key': apiKey,
          'X-User-Email': userEmail,
        },
      });
      const data = await res.json().catch(() => ({}));
      if (res.ok) {
        const contacts = Array.isArray(data.contacts) ? data.contacts : [];
        console.log(JSON.stringify({ success: true, count: contacts.length, contacts }, null, 2));
        return;
      }
      failures.push({ base, status: res.status, detail: data.error || data.message || 'non-ok response' });
    } catch (err) {
      failures.push({ base, detail: String((err && err.message) || err) });
    }
  }
  console.error(JSON.stringify({ success: false, failures }, null, 2));
  process.exit(1);
})();

module.exports = function (args, opts) {
  opts = opts || {};
  var res = { _: [] };
  var i = 0;

  function setKey(key, value) {
    key = key.replace(/^-+/, '');
    if (opts['boolean'] && opts['boolean'].indexOf(key) !== -1) {
      value = value === undefined ? true : value;
    }
    if (opts.string && opts.string.indexOf(key) !== -1) {
      value = value === undefined ? '' : String(value);
    }
    res[key] = value;
  }

  while (i < args.length) {
    var arg = args[i];

    if (/^--[^=]+=/.test(arg)) {
      var eq = arg.indexOf('=');
      setKey(arg.slice(0, eq), arg.slice(eq + 1));
    } else if (/^--.+/.test(arg)) {
      var name = arg.slice(2);
      if (i + 1 < args.length && !/^-/.test(args[i + 1])) {
        setKey(name, args[i + 1]);
        i += 1;
      } else {
        setKey(name, true);
      }
    } else if (/^-[^-]+/.test(arg) && arg.length > 1) {
      var shortName = arg.slice(1);
      if (i + 1 < args.length && !/^-/.test(args[i + 1])) {
        setKey(shortName, args[i + 1]);
        i += 1;
      } else {
        setKey(shortName, true);
      }
    } else {
      res._.push(arg);
    }

    i += 1;
  }

  return res;
};

